/* Browser-local career files. Each IndexedDB record is saved atomically. */
let onLoadCareers=false,activeSaveId=null,saveActionBusy=false,careerRecords=[],careerStorageError='',careerMigrationWarning='',careerStore=null;
let saveQueue=Promise.resolve(true),careerReady,importBusy=false;

function careerFeedback(message,isError=false){
 document.querySelectorAll('[data-career-feedback]').forEach(el=>el.remove());
 if(!message)return;
 const host=document.querySelector('dialog[open]')||document.getElementById('app');
 const el=document.createElement('div');el.dataset.careerFeedback='true';el.className='career-error';el.setAttribute('role',isError?'alert':'status');el.textContent=message;host.prepend(el);
}
function recordSummary(record){const {data,...metadata}=record;return metadata}
function teamSummary(data){const t=data.teams[data.gmCareer?.teamId??data.gmCareer?.lastTeamId??0];return{...readTeamBrand(t,message=>{throw Error(message)}),city:t.city,name:t.name,abbr:t.abbr,color:t.color,colors:copy(t.colors),logoAtlas:t.logoAtlas,logoIndex:t.logoIndex,w:t.w,l:t.l}}
function updateRecordCache(record){const meta=recordSummary(record),index=careerRecords.findIndex(x=>x.id===record.id);if(index<0)careerRecords.push(meta);else careerRecords[index]=meta}
function openCareerDatabase(){return openNormalizedCareerDatabase()}
function nextPlayedTime(){return new Date(Math.max(Date.now(),...careerRecords.map(r=>(Date.parse(r.lastPlayedAt)||0)+1))).toISOString()}
function newCareerId(){return 'career-'+crypto.randomUUID()}
function makeCareerRecord(data,options={}){return{id:options.id||newCareerId(),name:options.name||`${data.teams[0].city} ${data.teams[0].name} · ${data.year}`,createdAt:options.createdAt===undefined?new Date().toISOString():options.createdAt,lastPlayedAt:options.lastPlayedAt===undefined?nextPlayedTime():options.lastPlayedAt,importedAt:options.importedAt||null,updatedAt:new Date().toISOString(),leagueName:data.leagueName||'Dynasty Basketball League',gmName:data.gmName||'General Manager',year:data.year,day:data.day,totalDays:data.schedule.length,teamCount:data.teams.length,team:teamSummary(data),data:copy(data)}}
async function initializeCareers(backend){try{careerStore=backend||await openCareerDatabase();careerRecords=await careerStore.list();if(careerStore.requestPersistence)void careerStore.requestPersistence().then(result=>{careerStore.persistenceStatus=result});const marker=await careerStore.getMarker();let legacy;try{legacy=localStorage.getItem('hoops-dynasty-v1')}catch{}if(!marker&&legacy){try{const data=validateCareerData(JSON.parse(legacy)),record=makeCareerRecord(data,{id:'career-legacy-v1',createdAt:null,lastPlayedAt:null});await careerStore.migrate(record);updateRecordCache(record);/* Keep the verified legacy source as a recovery backup. */}catch(error){careerMigrationWarning='An older save could not be imported: '+error.message+' Its original data is preserved. Other save slots are still available.'}}careerStorageError=''}catch(error){careerStorageError=error.message||'Could not read your saves.'}render();return !careerStorageError}
async function requireCareerStore(){await careerReady;if(!careerStore||careerStorageError)throw Error(careerStorageError||'Career storage is not ready.')}
async function createCareerRecord(data){await requireCareerStore();await saveQueue;const normalized=validateCareerData(data),record=makeCareerRecord(normalized);await careerStore.put(record);updateRecordCache(record);return record}
function setSaveNotice(value){notice=value;const el=document.getElementById('save-status');if(el)el.textContent=value}
function save(){if(simulationHeadless()){simulationExecution.saveRequests++;return Promise.resolve(true);}if(!activeSaveId)return Promise.resolve(true);const id=activeSaveId,snapshot=copy(state);setSaveNotice('Saving…');saveQueue=saveQueue.then(async()=>{await requireCareerStore();const old=await (careerStore.metadata?careerStore.metadata(id):careerStore.get(id));if(!old)throw Error('The current save no longer exists.');const record={...old,data:snapshot,lastPlayedAt:nextPlayedTime(),updatedAt:new Date().toISOString(),year:snapshot.year,day:snapshot.day,totalDays:snapshot.schedule.length,teamCount:snapshot.teams.length,team:teamSummary(snapshot)};await careerStore.put(record);updateRecordCache(record);setSaveNotice('Saved in this browser');return true}).catch(error=>{setSaveNotice('Save failed — keep this tab open');toast(error.message);return false});return saveQueue}
function careerExists(){return careerRecords.length>0}
function latestCareer(){return [...careerRecords].sort((a,b)=>(Date.parse(b.lastPlayedAt)||0)-(Date.parse(a.lastPlayedAt)||0)||(Date.parse(b.createdAt)||0)-(Date.parse(a.createdAt)||0))[0]}
async function continueCareer(){await careerReady;const latest=latestCareer();if(latest)return openSavedCareer(latest.id);else if(careerStorageError)toast(careerStorageError);else loadCareer()}
async function openSavedCareer(id){if(saveActionBusy)return;saveActionBusy=true;careerFeedback('Loading career…');try{await requireCareerStore();if(!await saveQueue)throw Error('Your current progress could not be saved. Try again before switching careers.');const record=await careerStore.get(id,{adoptRevision:true});if(!record)throw Error('This save could not be found.');const loaded=validateCareerData(record.data);record.data=loaded;record.lastPlayedAt=nextPlayedTime();record.updatedAt=new Date().toISOString();if(careerStore.markOpened)record.revision=await careerStore.markOpened(id,record.lastPlayedAt);else await careerStore.put(record);updateRecordCache(record);state=loaded;activeSaveId=id;onLoadCareers=false;onSetup=false;onTitle=false;view='Overview';closeTitleModal();setSaveNotice('Saved in this browser');render();window.scrollTo(0,0)}catch(error){careerFeedback(error.message,true)}finally{saveActionBusy=false}}
async function returnToTitle(){if(!await save())return;onLoadCareers=false;onSetup=false;onTitle=true;render();window.scrollTo(0,0)}
function backFromCareers(){onLoadCareers=false;onTitle=true;onSetup=false;render();window.scrollTo(0,0)}
async function loadCareer(){careerFeedback('Opening saved careers…');await careerReady;careerFeedback('');onLoadCareers=true;onSetup=false;onTitle=true;renderLoadCareers();window.scrollTo(0,0)}
function dateLabel(value){if(!value)return 'Not recorded';const date=new Date(value);return Number.isNaN(date.getTime())?'Not recorded':date.toLocaleString(undefined,{year:'numeric',month:'short',day:'numeric',hour:'numeric',minute:'2-digit'})}
function renderLoadCareers(){applyLeagueTheme();const rows=[...careerRecords].sort((a,b)=>(Date.parse(b.lastPlayedAt)||0)-(Date.parse(a.lastPlayedAt)||0)||(Date.parse(b.createdAt)||0)-(Date.parse(a.createdAt)||0)),latest=latestCareer();document.getElementById('app').innerHTML=`<main class="setup-page careers-page"><header class="setup-top"><button onclick="backFromCareers()">← Back to title</button><span>HOOPS DYNASTY</span><small>THE ARCHIVE</small></header><div class="careers-wrap"><div class="setup-heading"><div><div class="eyebrow">PICK UP YOUR LEGACY</div><h1>LOAD CAREER</h1><p>${rows.length} saved ${rows.length===1?'career':'careers'} · Stored in this browser</p></div><div class="actions"><button class="setup-tool" onclick="document.getElementById('career-import').click()" ${importBusy?'disabled':''}>${importBusy?'Importing…':'↑ Import save file'}</button><button class="setup-start" onclick="startCareer()">New career +</button></div></div><input id="career-import" type="file" accept=".json,application/json" hidden onchange="importCareerFile(this)">${careerMigrationWarning?`<div class="career-error" role="alert">${escapeHTML(careerMigrationWarning)}</div>`:''}${careerStorageError?`<div class="career-error" role="alert">${escapeHTML(careerStorageError)}</div>`:''}<div class="career-files">${rows.map(r=>renderCareerCard(r,r.id===latest?.id)).join('')||`<section class="empty-careers"><h2>Your next dynasty starts here.</h2><p>Create a new career, or import an exported Hoops Dynasty save.</p><button class="setup-start" onclick="startCareer()">New career →</button></section>`}</div><p class="archive-note">New careers get their own save slot. Export a save to keep a backup or move it to another browser.</p></div></main>`}
