function closeSaveMenus(){document.querySelectorAll('.save-actions[open]').forEach(d=>d.open=false)}
function renameCareerDialog(id){closeSaveMenus();const r=careerRecords.find(r=>r.id===id);if(!r)return;editorModal('Rename save file',`<form onsubmit="renameCareer(event,'${id}')"><label>Save name<input name="saveName" required maxlength="80" value="${escapeHTML(r.name)}" autofocus></label><p class="muted">This changes the save label. Your league and team names stay the same.</p><div class="actions"><button type="button" onclick="closeTitleModal()">Cancel</button><button class="primary">Save name</button></div></form>`)}
